// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL =  import.meta.env.VITE_SUPABASE_URL
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY;
// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    storage: localStorage
  }
});

// Initialize database tables and data if needed
export const initializeSupabaseData = async () => {
  // Check if user is authenticated
  const { data: { user } } = await supabase.auth.getUser();
  
  if (!user) {
    console.log("User not authenticated. Some operations may be restricted.");
    return;
  }

  try {
    // Initialize categories if they don't exist
    const { data: existingCategories } = await supabase
      .from('categories')
      .select('count')
      .single();

    if (!existingCategories || existingCategories.count === 0) {
      // Add default categories
      const defaultCategories = [
        // { name: 'Salary', type: 'income', color: '#10B981', description: 'Regular income from employment' },
       
      ];

      await supabase.from('categories').insert(defaultCategories);
      console.log("Default categories initialized successfully");
    }

    // Other initializations can be added as needed

  } catch (error) {
    console.error("Error initializing Supabase data:", error);
  }
};
